export const DatePickerWithFilter = {
  render: () => {
    const [date, setDate] = useState({ from: currentDay.toDate(), to: undefined });

    return (
      <Stack height={600}>
        <DatePicker
          filterConfig={{
            filterType: 'preset',
          }}
          value={date}
          onChange={setDate}
        />

        <DatePicker
          filterConfig={{ label: 'My date', filterType: 'added' }}
          onClear={() => {
            setDate({ from: undefined, to: undefined });
          }}
          value={date}
          onChange={setDate}
        />

        <DatePicker
          value={date}
          onChange={setDate}
          isRangePicker
          filterConfig={{
            filterType: 'preset',
          }}
        />

        <DatePicker
          value={date}
          onChange={setDate}
          onClear={() => {
            setDate({ from: undefined, to: undefined });
          }}
          isRangePicker
          filterConfig={{ label: 'Annotation date', filterType: 'added' }}
          options={[
            {
              label: 'Today',
              value: 'today',
              dates: [today, today],
